/**
 * Writes `packages/contracts/addresses/<slug>.json` for one chain, from the SDK.
 *
 * Foundry cannot import TypeScript and no address may be typed twice, so the deploy
 * script reads a generated file rather than carrying its own copy. This is the
 * per-chain sibling of `gen-contract-addresses.mjs`, which does the same job for Arc
 * and stays as it is: Arc's addresses come from its own hand-verified table, and
 * every other chain's USDC comes from `CCTP_CHAINS`, which was read off each chain.
 *
 * Imports the built SDK rather than regex-parsing the source. The Arc generator
 * parses, which works because it reads one literal block; picking a chain out of
 * `CCTP_CHAINS` by name is not something to do with a regular expression.
 *
 * Usage: node scripts/gen-chain-addresses.mjs Base_Sepolia
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const sdk = await import(
  path.join(root, 'packages/sdk/dist/index.js').replace(/\\/g, '/').replace(/^([A-Za-z]):/, 'file:///$1:')
);

const { CCTP_CHAINS, ARC_TESTNET_CHAIN_ID } = sdk;

const name = process.argv[2];
if (!name) {
  throw new Error('usage: node scripts/gen-chain-addresses.mjs <CctpChainName>');
}
const chain = CCTP_CHAINS[name];
if (!chain) {
  throw new Error(`unknown chain "${name}". Known: ${Object.keys(CCTP_CHAINS).join(', ')}`);
}
if (chain.chainId === ARC_TESTNET_CHAIN_ID) {
  throw new Error('Arc has its own generator and its own deployment; do not re-run it here.');
}

/**
 * Ecosystem singletons, at the same address on every chain that has them.
 *
 * Not copied from Arc's table by coincidence: these are deployed through a
 * deterministic factory precisely so the address does not vary. The deploy script
 * still checks each one has code before it uses it, because "usually deployed" is
 * not the same as "deployed here".
 */
const PERMIT2 = '0x000000000022D473030F116dDEE9F6B43aC78BA3';
const MULTICALL3 = '0xcA11bde05977b3631167028862bE2a173976CA11';
const CREATE2_FACTORY = '0x4e59b44847b379578588920cA78FbF26c0B4956C';

/** `Base_Sepolia` -> `base-sepolia`, so a filename is a filename. */
const slug = name.toLowerCase().replace(/_/g, '-');

const out = {
  _generated: 'DO NOT EDIT - generated by scripts/gen-chain-addresses.mjs',
  chain: name,
  chainId: chain.chainId,
  USDC: chain.usdc,
  PERMIT2,
  MULTICALL3,
  CREATE2_FACTORY,
};

const dir = path.join(root, 'packages/contracts/addresses');
fs.mkdirSync(dir, { recursive: true });
fs.writeFileSync(path.join(dir, `${slug}.json`), JSON.stringify(out, null, 2) + '\n');
console.log(`addresses/${slug}.json yazildi (chainId ${chain.chainId}, USDC ${chain.usdc})`);
console.log(`CHAIN_SLUG=${slug}`);
